using System;using System.Linq;using System.IO;using System.Reflection;using Verse;using UnityEngine;using PlayableRecreation;using PlayableRecreation.UI;using Chess;using Chess.Core;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;var d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().First();var f=BindingFlags.Instance|BindingFlags.NonPublic;var w=(ChessGameWorker)typeof(Dialog_MiniGame).GetField("worker",f).GetValue(d);w.StartNew(2);var core=(ChessGame)typeof(ChessGameWorker).GetField("game",f).GetValue(w);foreach(var mv in new[]{new[]{21,37},new[]{100,68},new[]{22,54},new[]{115,55}}){var legal=core.Legal.Take(core.LegalCount).First(m=>m.From==mv[0]&&m.To==mv[1]);typeof(ChessGameWorker).GetMethod("Commit",f).Invoke(w,new object[]{legal,Time.realtimeSinceStartup});}var pair=new[]{(Pawn)typeof(Dialog_MiniGame).GetField("seatedPawn",f).GetValue(d),(Pawn)typeof(Dialog_MiniGame).GetField("opponentPawn",f).GetValue(d)};Host.State["idleParticipants"]=pair;Host.State["idleDialog"]=d;var b=(Thing)Host.State["chess"];float start=Time.realtimeSinceStartup;int last=-1;var log=Host.Root+"/idle-hover-r2.txt";File.WriteAllText(log,"Actual legal checkmate; idle clock is real seconds. Observe hover externally.\n");Host.Watch=()=>{float e=Time.realtimeSinceStartup-start;if((int)e!=last){last=(int)e;File.AppendAllText(log,e.ToString("F2")+" mouse="+UI.MousePositionOnUIInverted+" focused="+Application.isFocused+" rect="+d.windowRect+" released="+typeof(Dialog_MiniGame).GetField("released",f).GetValue(d)+" until="+((float)typeof(Dialog_MiniGame).GetField("releaseAt",f).GetValue(d)-Time.realtimeSinceStartup).ToString("F2")+" window="+Find.WindowStack.Windows.Contains(d)+" held="+TogetherMatch.ShouldHold(b,pair[0])+","+TogetherMatch.ShouldHold(b,pair[1])+" jobs="+pair[0].CurJobDef+","+pair[1].CurJobDef+"\n");}if(e>32){Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;return "Finished real game; hover inside >10s then move outside to observe release (32s watcher).";}}

